from PIL import Image
import numpy as np,cv2
I=np.array(Image.open('first_frame.png').convert('RGB'))
for criterion in ['v50','v80','neutral90','brown']:
 if criterion=='v50': m=np.max(I,2)<50
 elif criterion=='v80': m=np.mean(I,2)<80
 elif criterion=='neutral90': m=(np.mean(I,2)<100)&((I.max(2)-I.min(2))<25)
 else: m=(I[:,:,0]>I[:,:,1]*1.2)&(I[:,:,1]>I[:,:,2]*1.2)&(I[:,:,0]<160)
 print('\\n',criterion)
 for y in range(30,112,2):
  idx=np.where(m[y])[0]; runs=[]
  if len(idx):
   sp=np.where(np.diff(idx)>1)[0]; starts=np.r_[0,sp+1];ends=np.r_[sp,len(idx)-1]
   for a,b in zip(starts,ends):
    if idx[b]-idx[a]+1>=2: runs.append(f'{idx[a]}-{idx[b]}')
  print(y,','.join(runs))
